@interface BRSlotGamePickerViewController () <UICollectionViewDataSource, UICollectionViewDelegateFlowLayout>
@property (nonatomic,strong) UICollectionView *collectionView;
@property (nonatomic, strong) AVAudioEngine *casinoEngine;
@property (nonatomic, strong) AVAudioPlayerNode *casinoNode;
@property (nonatomic, strong) AVAudioPCMBuffer *casinoBuffer;
@property (nonatomic,strong) NSArray<BRGameRecord *> *importableGames;
@property (nonatomic, strong) BRSlotChatBar *loungeHelper; // never attached or started: owns the winners-board and profile flows for the buttons in the nav bar
@property (nonatomic, strong) UIButton *profileAvatarButton; // the nav-bar profile button; shows the player's photo once they have one
@property (nonatomic, strong) UIButton *soundButton; // the nav-bar slot sound on/off toggle
@end

@implementation BRSlotGamePickerViewController
- (void)setupCasinoAmbience {
    [[AVAudioSession sharedInstance] setCategory:AVAudioSessionCategoryAmbient error:nil];
    NSURL *url = [[NSBundle mainBundle] URLForResource:@"crowded_casino" withExtension:@"caf" subdirectory:@"sounds"];
    if (!url) url = [[NSBundle mainBundle] URLForResource:@"crowded_casino" withExtension:@"caf"];
    if (!url) url = [[NSBundle mainBundle] URLForResource:@"crowded_casino" withExtension:@"mp3" subdirectory:@"sounds"];
    if (!url) url = [[NSBundle mainBundle] URLForResource:@"crowded_casino" withExtension:@"mp3"];
    if (url) {
        // Gapless loop: decode the file to a PCM buffer on a player
        // node. AVAudioPlayer looping replays a compressed file's
        // priming/padding samples as a silence gap at every wrap; a
        // PCM buffer scheduled with BufferLoops loops sample-accurately.
        // Same rule as the machines: a bad sound file stays silent,
        // it never crashes the picker (AVAudioFile throws on some
        // corrupt/mislabeled inputs where AVAudioPlayer returned nil).
        @try {
        AVAudioFile *file = [[AVAudioFile alloc] initForReading:url error:nil];
        AVAudioFormat *format = file.processingFormat;
        if (file && file.length > 0 && format && format.sampleRate > 0 && format.channelCount > 0) {
            AVAudioPCMBuffer *buffer = [[AVAudioPCMBuffer alloc] initWithPCMFormat:format frameCapacity:(AVAudioFrameCount)file.length];
            if (buffer && [file readIntoBuffer:buffer error:nil] && buffer.frameLength > 0) {
                // Trim a zero-padded decode tail (VBR length overstate,
                // as in the machines' loop builder). No-op when the
                // file's tail is real audio.
                if (buffer.format.commonFormat == AVAudioPCMFormatFloat32 && !buffer.format.interleaved && buffer.floatChannelData) {
                    AVAudioFrameCount frames = buffer.frameLength;
                    float * const *channels = buffer.floatChannelData;
                    NSUInteger channelCount = buffer.format.channelCount;
                    while (frames > 0) {
                        BOOL silent = YES;
                        for (NSUInteger c = 0; c < channelCount; c++) {
                            if (fabsf(channels[c][frames - 1]) > 0.0005f) { silent = NO; break; }
                        }
                        if (!silent) break;
                        frames--;
                    }
                    buffer.frameLength = frames;
                }
            }
            if (buffer && buffer.frameLength > 0) {
                self.casinoBuffer = buffer;
                self.casinoEngine = [AVAudioEngine new];
                self.casinoNode = [AVAudioPlayerNode new];
                [self.casinoEngine attachNode:self.casinoNode];
                [self.casinoEngine connect:self.casinoNode to:self.casinoEngine.mainMixerNode format:file.processingFormat];
                self.casinoEngine.mainMixerNode.outputVolume = .5;
                [self.casinoNode scheduleBuffer:buffer atTime:nil options:AVAudioPlayerNodeBufferLoops completionHandler:nil];
            }
        }
        } @catch (NSException *e) {
        }
    }
}
- (void)viewDidLoad { [super viewDidLoad]; [self setupCasinoAmbience]; self.navigationController.modalInPresentation=YES; /* Pin the slot flow: a swipe down must not dismiss the picker or a game mid-session; the Back button is the way out. */ self.loungeHelper=[[BRSlotChatBar alloc] initWithRoomID:@"brainrot-classic"]; self.loungeHelper.hostViewController=self; [NSNotificationCenter.defaultCenter addObserver:self selector:@selector(profileDidUpdate) name:BRSlotProfileDidUpdateNotification object:nil]; /* One title per page: the SLOT GAMES header below is this screen's only title; no nav-bar duplicate. */ self.view.backgroundColor=[UIColor colorWithRed:.04 green:.02 blue:.09 alpha:1]; self.navigationItem.leftBarButtonItem=[[UIBarButtonItem alloc] initWithCustomView:[self navigationButton]]; self.navigationItem.rightBarButtonItems=@[[[UIBarButtonItem alloc] initWithCustomView:(self.profileAvatarButton=[self profileButton])],[[UIBarButtonItem alloc] initWithCustomView:[self winsButton]],[[UIBarButtonItem alloc] initWithCustomView:(self.soundButton=[self soundToggleButton])]]; self.importableGames=BRGameLibrary.shared.allRecords;
    UILabel *header=[UILabel new]; header.text=NSLocalizedString(@"BRSlot.Picker.Header", nil); header.font=[UIFont systemFontOfSize:28 weight:UIFontWeightBlack]; header.adjustsFontSizeToFitWidth=YES; header.minimumScaleFactor=.55; header.textColor=[UIColor colorWithRed:1 green:.78 blue:.18 alpha:1]; header.translatesAutoresizingMaskIntoConstraints=NO; [self.view addSubview:header];
    UILabel *detail=[UILabel new];
    detail.adjustsFontSizeToFitWidth = YES;
    detail.minimumScaleFactor = 0.5; detail.text=NSLocalizedString(@"BRSlot.Picker.Detail", nil); detail.textColor=[UIColor colorWithWhite:.68 alpha:1]; detail.font=[UIFont systemFontOfSize:14 weight:UIFontWeightMedium]; detail.numberOfLines=2; detail.translatesAutoresizingMaskIntoConstraints=NO; [self.view addSubview:detail];
    UICollectionViewFlowLayout *layout=[UICollectionViewFlowLayout new]; layout.minimumLineSpacing=13; layout.minimumInteritemSpacing=13; layout.sectionInset=UIEdgeInsetsMake(12,18,24,18); self.collectionView=[[UICollectionView alloc] initWithFrame:CGRectZero collectionViewLayout:layout]; self.collectionView.backgroundColor=UIColor.clearColor; self.collectionView.dataSource=self; self.collectionView.delegate=self; self.collectionView.alwaysBounceVertical=YES; self.collectionView.translatesAutoresizingMaskIntoConstraints=NO; [self.collectionView registerClass:BRSlotPickerCard.class forCellWithReuseIdentifier:@"SlotCard"]; [self.view addSubview:self.collectionView];
    [NSLayoutConstraint activateConstraints:@[[header.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor constant:18],[header.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor constant:24],[header.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor constant:-24],[detail.topAnchor constraintEqualToAnchor:header.bottomAnchor constant:6],[detail.leadingAnchor constraintEqualToAnchor:header.leadingAnchor],[detail.trailingAnchor constraintEqualToAnchor:header.trailingAnchor],[self.collectionView.topAnchor constraintEqualToAnchor:detail.bottomAnchor constant:10],[self.collectionView.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[self.collectionView.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor],[self.collectionView.bottomAnchor constraintEqualToAnchor:self.view.bottomAnchor]]]; }
- (void)viewWillAppear:(BOOL)animated { [super viewWillAppear:animated]; [self.loungeHelper fetchOwnProfile]; [self refreshProfileAvatarButton]; [self refreshSoundButton]; self.importableGames=BRGameLibrary.shared.allRecords; [self.collectionView reloadData]; if (self.casinoNode && !self.casinoNode.isPlaying && BRSlotSoundEnabled()) { @try { if (!self.casinoEngine.isRunning) [self.casinoEngine startAndReturnError:nil]; [self.casinoNode play]; } @catch (NSException *e) { } } }
- (void)viewWillDisappear:(BOOL)animated { [super viewWillDisappear:animated]; [self.casinoNode pause]; }
- (UIButton *)navigationButton { UIButton *button=[UIButton buttonWithType:UIButtonTypeSystem]; [button setTitle:NSLocalizedString(@"BRSlot.Picker.Back", nil) forState:UIControlStateNormal]; button.titleLabel.font=[UIFont systemFontOfSize:12 weight:UIFontWeightBlack]; button.tintColor=[UIColor colorWithRed:1 green:.78 blue:.18 alpha:1]; button.backgroundColor=[UIColor colorWithRed:.13 green:.05 blue:.23 alpha:.96]; button.layer.cornerRadius=9; button.layer.borderWidth=1; button.layer.borderColor=[UIColor colorWithRed:1 green:.78 blue:.18 alpha:.72].CGColor; button.contentEdgeInsets=UIEdgeInsetsMake(7,10,7,10); [button sizeToFit]; [button addTarget:self action:@selector(close) forControlEvents:UIControlEventTouchUpInside]; return button; }
- (UIButton *)winsButton { UIButton *button=[UIButton buttonWithType:UIButtonTypeSystem]; [button setTitle:NSLocalizedString(@"BRSlot.Lounge.Wins", nil) forState:UIControlStateNormal]; button.titleLabel.font=[UIFont systemFontOfSize:12 weight:UIFontWeightBlack]; button.tintColor=[UIColor colorWithRed:1 green:.78 blue:.18 alpha:1]; button.backgroundColor=[UIColor colorWithRed:.13 green:.05 blue:.23 alpha:.96]; button.layer.cornerRadius=9; button.layer.borderWidth=1; button.layer.borderColor=[UIColor colorWithRed:1 green:.78 blue:.18 alpha:.72].CGColor; button.contentEdgeInsets=UIEdgeInsetsMake(7,10,7,10); [button sizeToFit]; [button addTarget:self action:@selector(showWinnersBoard) forControlEvents:UIControlEventTouchUpInside]; return button; }
- (UIButton *)soundToggleButton { UIButton *button=[UIButton buttonWithType:UIButtonTypeSystem]; button.backgroundColor=[UIColor colorWithRed:.13 green:.05 blue:.23 alpha:.96]; button.layer.cornerRadius=9; button.layer.borderWidth=1; button.layer.borderColor=[UIColor colorWithRed:1 green:.78 blue:.18 alpha:.72].CGColor; button.tintColor=[UIColor colorWithRed:1 green:.78 blue:.22 alpha:1]; button.contentEdgeInsets=UIEdgeInsetsMake(7,9,7,9); [button addTarget:self action:@selector(toggleSlotSound) forControlEvents:UIControlEventTouchUpInside]; [self refreshSoundButton:button]; [button sizeToFit]; return button; }
- (void)refreshSoundButton { [self refreshSoundButton:self.soundButton]; }
- (void)refreshSoundButton:(UIButton *)button { if (!button) return; [button setImage:[UIImage systemImageNamed:BRSlotSoundEnabled() ? @"speaker.fill" : @"speaker.slash.fill"] forState:UIControlStateNormal]; }
- (void)toggleSlotSound { BOOL on = !BRSlotSoundEnabled(); BRSlotSetSoundEnabled(on); [self refreshSoundButton]; if (!on) { [self.casinoNode pause]; } else if (self.casinoNode && !self.casinoNode.isPlaying) { @try { if (!self.casinoEngine.isRunning) [self.casinoEngine startAndReturnError:nil]; [self.casinoNode play]; } @catch (NSException *e) { } } }
- (UIButton *)profileButton { UIButton *button=[UIButton buttonWithType:UIButtonTypeSystem]; [button setImage:[UIImage systemImageNamed:@"person.crop.circle"] forState:UIControlStateNormal]; button.tintColor=[UIColor colorWithRed:1 green:.78 blue:.22 alpha:1]; button.backgroundColor=[UIColor colorWithRed:.13 green:.05 blue:.23 alpha:.96]; button.layer.cornerRadius=9; button.layer.borderWidth=1; button.layer.borderColor=[UIColor colorWithRed:1 green:.78 blue:.18 alpha:.72].CGColor; button.contentEdgeInsets=UIEdgeInsetsMake(7,9,7,9); button.translatesAutoresizingMaskIntoConstraints=NO; [NSLayoutConstraint activateConstraints:@[[button.widthAnchor constraintEqualToConstant:40],[button.heightAnchor constraintEqualToConstant:40]]]; [button addTarget:self action:@selector(showProfileEditor) forControlEvents:UIControlEventTouchUpInside]; return button; }
- (void)showWinnersBoard { [self.loungeHelper showWinnersBoard]; }
- (void)showProfileEditor { [self.loungeHelper showProfileEditor]; }
- (void)profileDidUpdate { [self refreshProfileAvatarButton]; [self.collectionView reloadData]; }
// The avatar photo renders AlwaysOriginal: the profile button is a system
// button with a gold tintColor, and a photo left on Automatic renders as a
// template — a solid gold square. The SF Symbol placeholder stays templated.
- (void)refreshProfileAvatarButton { NSString *url = self.loungeHelper.profileAvatarURL; if (!url.length || !self.profileAvatarButton) return; __weak typeof(self) weakSelf = self; [BRSlotChatBar loadAvatarThumbnailForURL:url points:36 completion:^(UIImage *image) { if (!image) return; __strong typeof(weakSelf) self = weakSelf; if (!self) return; self.profileAvatarButton.contentEdgeInsets = UIEdgeInsetsMake(4,4,4,4); [self.profileAvatarButton setImage:[image imageWithRenderingMode:UIImageRenderingModeAlwaysOriginal] forState:UIControlStateNormal]; self.profileAvatarButton.imageView.contentMode = UIViewContentModeScaleAspectFill; self.profileAvatarButton.imageView.layer.cornerRadius = 9; self.profileAvatarButton.imageView.clipsToBounds = YES; }]; }
- (void)dealloc { [NSNotificationCenter.defaultCenter removeObserver:self]; }
- (void)close { if (self.onReturnToBrainRotMenu) self.onReturnToBrainRotMenu(); else [self dismissViewControllerAnimated:YES completion:nil]; }
- (NSInteger)collectionView:(UICollectionView *)collectionView numberOfItemsInSection:(NSInteger)section { return 14+self.importableGames.count; }
- (BRSlotPickerCardKind)kindAtIndex:(NSInteger)index { static const BRSlotPickerCardKind order[14]={BRSlotPickerCardKindPlunder,BRSlotPickerCardKindPlunderVIP,BRSlotPickerCardKindGolden,BRSlotPickerCardKindGoldenVIP,BRSlotPickerCardKindPhoenix,BRSlotPickerCardKindPhoenixVIP,BRSlotPickerCardKindStarlight,BRSlotPickerCardKindStarlightVIP,BRSlotPickerCardKindPenguin,BRSlotPickerCardKindPenguinVIP,BRSlotPickerCardKindClassic,BRSlotPickerCardKindPenny,BRSlotPickerCardKindCreate,BRSlotPickerCardKindCommunity}; return index<14 ? order[index] : BRSlotPickerCardKindSaved; }
